 30	    private void validateItems(CheckoutRequestDto request) {
 31	        if (request.getItems() == null || request.getItems().isEmpty()) {
 32	            throw new InvalidOrderException();
 33	        }
 34	
 35	        Set<String> seenSkus = new HashSet<>();
 36	        for (var item : request.getItems()) {
 37	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
 38	                throw new InvalidOrderException();
 39	            }
 40	            if (!seenSkus.add(item.getSku())) {
 41	                throw new InvalidOrderException();
 42	            }
 43	        }
 44	
 45	        for (var item : request.getItems()) {
 46	            Product product = productService.getProduct(item.getSku());
 47	            if (product == null) {
 48	                throw new UnknownProductException();
 49	            }
 50	            if (product.isDiscontinued()) {
 51	                throw new ProductDiscontinuedException();
 52	            }
 53	            if (product.getStock() < item.getQuantity()) {
 54	                throw new InsufficientStockException();
 55	            }
 56	        }
