136	    private BigDecimal calculateTotalWeight(CheckoutRequestDto request) {
137	        BigDecimal totalWeight = BigDecimal.ZERO;
138	        for (var item : request.getItems()) {
139	            Product product = productService.getProduct(item.getSku());
140	            BigDecimal itemWeight = product.getWeightKg().multiply(new BigDecimal(item.getQuantity()));
141	            totalWeight = totalWeight.add(itemWeight);
142	        }
