 81	    private void validateShippingMethod(CheckoutRequestDto request) {
 82	        ShippingMethod method;
 83	        try {
 84	            method = ShippingMethod.valueOf(request.getShippingMethod());
 85	        } catch (IllegalArgumentException e) {
 86	            throw new InvalidShippingMethodException();
 87	        }
 88	
 89	        if (method == ShippingMethod.COURIER) {
 90	            BigDecimal totalWeight = calculateTotalWeight(request);
 91	            if (totalWeight.compareTo(new BigDecimal("5")) > 0) {
 92	                throw new ShippingMethodUnavailableException();
 93	            }
 94	        }
 95	    }
